use std::{collections::BTreeMap,fs};fn main(){let mut rows=BTreeMap::new();for l in fs::read_to_string("research/hec_residual_span_20261116/one-core-cold/CONTROL.tsv").unwrap().lines().skip(1){let v:Vec<String>=l.split('\t').map(str::to_string).collect();assert_eq!(v.len(),13);let k:Vec<u64>=v[..6].iter().map(|x|x.parse().unwrap()).collect();assert_eq!(v[6],v[7]);assert_eq!(v[8],"true");let c:Vec<u64>=v[12].split(',').map(|x|x.parse().unwrap()).collect();assert_eq!(c.len(),16);assert_eq!(c[8],2*c[7]+c[5]+c[6]);if k[3]==1{let mut old=k.clone();old[3]=0;let prior:&Vec<String>=&rows[&old];assert_eq!(&prior[4..],&v[4..]);}assert!(rows.insert(k,v).is_none());}assert_eq!(rows.len(),96);let mut ranges=BTreeMap::<bool,(f64,f64)>::new();println!("p\tsm\tcase\tmodulus\tbaseline_REDC\tcandidate_REDC\tbaseline_over_candidate_REDC\tbaseline_rows\tcandidate_rows\tbaseline_anchors\tcandidate_anchors");for(k,v)in &rows{if k[3]!=0||k[4]!=0{continue}let mut other=k.clone();other[4]=1;let b=&rows[&other];assert_eq!(&v[6..9],&b[6..9]);let a:Vec<u64>=v[12].split(',').map(|x|x.parse().unwrap()).collect();let bb:Vec<u64>=b[12].split(',').map(|x|x.parse().unwrap()).collect();let ratio=a[8]as f64/bb[8]as f64;let e=ranges.entry(k[0]==k[5]).or_insert((ratio,ratio));e.0=e.0.min(ratio);e.1=e.1.max(ratio);println!("{}\t{}\t{}\t{}\t{}\t{}\t{ratio:.6}\t{}\t{}\t{}\t{}",k[0],k[1],k[2],k[5],a[8],bb[8],v[9],b[9],v[10],b[10]);}for(base,(lo,hi))in ranges{eprintln!("base_field={base} min_REDC_ratio={lo:.6} max_REDC_ratio={hi:.6}");}eprintln!("records=96 all_12_workloads_complete=true exact_repeats=true same_targets=true REDC_identity=true");}
